  "encoding": {
    "x": {
      "field": "Station Name",
      "type": "nominal",
      "title": "Station"
    },
    "y": {
      "field": "Max Temp",
      "type": "quantitative",
      "title": "Hottest Temperature Recorded (°C)"
    }
  },
  "params": [
    {
      "name": "agg",
      "value": {"aggregate": "max", "field": "Max Temp"},
      "select": {
        "type": "facet",
        "fields": ["Station Name"],
        "op": "mean"
      }
    }
  ]
}

{
  "mark": "point",
  "encoding": {
    "x": {
      "field": "Date",
      "type": "temporal"
    },
    "y": {
      "aggregate": "min",
      "field": "Min Temp",
      "type": "quantitative"
    },
    "color": {
      "field": "Station Name",
      "type": "nominal"
    }
  },
  "transform": [
    {
      "calculate": "datum.Min Temp === d3.min(datum.Station_Name, (d) => d.Min Temp)",
      "as": "isColdestMinTemp"
    }
  ],
  "selection": {
    "coldestMinTemp": {
      "type": "single",
      "on": "mouseover",
      "fields": ["Station Name"]
    }
  },
  "layer": [
    {
      "mark": {
        "type": "rule",
        "color": "lightgray"
      }
    }
  ]
}

{
  "mark": "line",
  "encoding": {
    "x": {
      "field": "Date",
      "type": "temporal",
      "timeUnit": "month",
      "title": "Month"
    },
    "y": {
      "aggregate": "mean",
      "field": "Max Temp",
      "type": "quantitative",
      "title": "Average Maximum Temperature (°C)"
    },
    "color": {
      "field": "Station Name",
      "type": "nominal",
      "title": "Station"
    }
  },
  "params": [
    {
      "name": "filterParam",
      "select": {
        "fields": ["Station Name"],
        "op": "in",
        "value": ["Cerro Azul", "Playa Norte"]
      }
    }
  ]
}

{
  "transform": [
    {
      "timeUnit": {"field": "Date", "unit": "date"},
      "groupby": ["Station Name"],
      "aggregate": [{"op": "count", "field": "Date", "as": "Distinct Dates"}]
    }
  ],
  "mark": "bar",
  "encoding": {
    "x": {"field": "Station Name", "type": "nominal", "title": "Station Name"},
    "y": {"field": "Distinct Dates", "type": "quantitative", "title": "Number of Distinct Dates"}
  }
}

